/**
 * Merge server-provided translations over the bundled catalog (Laravel sync).
 * The backend can POST/GET a `{ locale: { key: value } }` map; call this to apply
 * it. Missing keys always fall back through the requested locale → English.
 */
export function registerTranslations(locale: Locale, dict: Record<string, string>): void {
  MESSAGES[locale] = { ...(MESSAGES[locale] ?? {}), ...dict };
}

/** Resolve a key for a locale, falling back to English, then the key itself. */
export function translate(locale: Locale, key: string, vars?: Record<string, string | number>): string {
  const raw = MESSAGES[locale]?.[key] ?? MESSAGES.en[key] ?? key;
  if (!vars) return raw;
  return raw.replace(/\{(\w+)\}/g, (_m, name: string) => String(vars[name] ?? `{${name}}`));
}
